    public static class PoiContentQa
    {
        public static string Phase{get;private set;}="idle";
        private static string Root=>Path.GetFullPath("Captures/base-defense-poi-expansion");
        private static WorldSaveService save;private static PlayerInventory bag;private static WorldGenerator world;private static ContentCatalog catalog;private static NetworkSession host;private static NetworkPlayer actor;
        private static void Log(string s){Directory.CreateDirectory(Root);File.AppendAllText(Root+"/live.tsv",DateTime.UtcNow.ToString("O")+"\t"+Phase+"\t"+s+"\n");}
        private static void Check(bool ok,string s){Log((ok?"PASS ":"FAIL ")+s);if(!ok)throw new InvalidOperationException(s);}
        private static void Step(string s){Phase=s;Log("begin");}
        private static IEnumerator Guard(IEnumerator flow){var stack=new Stack<IEnumerator>();stack.Push(flow);while(stack.Count>0){bool more;object value;try{more=stack.Peek().MoveNext();value=more?stack.Peek().Current:null;}catch(Exception e){Phase="failed";Log(e.ToString());yield break;}if(!more){stack.Pop();continue;}if(value is IEnumerator child)stack.Push(child);else yield return value;}Phase="complete";Log("complete");}
        private static IEnumerator Shot(string name){if(Application.isBatchMode)yield break;yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Root+"/"+name+".png");yield return new WaitForEndOfFrame();yield return null;}
        private static void Move(Vector2 p){CampLootPanel.CloseFocused();var commands=bag.GetComponent<PlayerInputCommands>();commands.Session.CloseInventory();commands.SetMove(Vector2.zero);bag.transform.position=p;bag.GetComponent<Rigidbody2D>().position=p;bag.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;Physics2D.SyncTransforms();world.Chunks.Reconcile();world.Chunks.DrainPending();NetworkCreatureWorld.Active?.FlushPending();}
        private static WorldAnchor Anchor(WorldAnchorKind kind)=>world.Map.Continental.Anchors.Where(a=>a.Kind==kind).OrderBy(a=>a.Position.sqrMagnitude).First();
        private static PoiSite Approach(WorldAnchorKind kind){var a=Anchor(kind);Move(a.Position+Vector2.down*3);var site=world.Chunks.ActivePoiSites[a.Id];Move((Vector2)site.Location.position+Vector2.down*1.5f);bag.GetComponent<CharacterFacing>().Face(Vector2.up);return site;}
        private static void Empty()=>bag.Model.Restore(new InventoryModel(36).Capture(),catalog);
        private static void Full(){Empty();bag.Model.Add(catalog.Item("stone"),catalog.Item("stone").MaxStack*36);}
        private static void Select(string id,int count=1){if(bag.Model.CountItem(catalog.Item(id))<count)bag.Model.Add(catalog.Item(id),count);var slot=Enumerable.Range(0,36).First(i=>bag.Model.GetSlot(i).Item==catalog.Item(id));if(slot>=9){bag.Model.MoveStack(slot,bag.SelectedIndex);slot=bag.SelectedIndex;}bag.SelectSlot(slot);}
        private static IEnumerator Interact(PoiSite site){bag.GetComponent<CharacterFacing>().Face((Vector2)site.Location.position-(Vector2)bag.transform.position);yield return null;Check(bag.GetComponent<PlayerInteraction>().Target==site,"actual interact target "+site.Kind);Check(bag.GetComponent<PlayerInteraction>().TryInteract(),"actual interact action "+site.Kind);yield return null;}
        private static void FreezeGuards(){foreach(var e in UnityEngine.Object.FindObjectsByType<EnemyController>(FindObjectsSortMode.None))e.enabled=false;}
        private static IEnumerator Revisit(PoiSite site,string label)
        {var id=site.Id;var at=(Vector2)site.transform.position;var before=JsonUtility.ToJson(site.State);Move(world.Map.Spawn);yield return null;Check(!world.Chunks.ActivePoiSites.ContainsKey(id),label+" representation retired");Move(at+Vector2.down*2);yield return null;Check(JsonUtility.ToJson(world.Chunks.PoiState(id))==before,label+" exact finite state survives unload/reload");}
