        {ContentExpansionQa.Prepare();save=ContentExpansionQa.S;bag=save.Player;world=save.World;catalog=save.Catalog;world.Animals.enabled=world.Renewal.enabled=false;bag.GetComponent<PlayerSurvival>().enabled=false;Application.runInBackground=true;save.StartCoroutine(Guard(Single()));}
