            Step("all-eight-poi");foreach(WorldAnchorKind kind in Enum.GetValues(typeof(WorldAnchorKind)))
            {var a=Anchor(kind);Move(a.Position+Vector2.down*3);FreezeGuards();yield return new WaitForSecondsRealtime(.15f);Check(world.Chunks.IsActive(a.Position),"actual active terrain "+kind);Log(kind+" id="+a.Id+" position="+a.Position);yield return Shot("01-"+kind);}
            Step("campsite");Empty();var camp=Approach(WorldAnchorKind.Campsite);Check(!camp.State.Legacy && camp.Loot.Count(s=>s.Count>0)==3,"new campsite bounded variant");yield return Interact(camp);Check(CampLootPanel.IsOpen,"existing supplies modal");yield return Shot("02-campsite-open");var before=JsonUtility.ToJson(camp.State);Full();Check(!camp.Take(bag,0,camp.Revision) && JsonUtility.ToJson(camp.State)==before,"full bag leaves campsite unchanged");Empty();var revision=camp.Revision;var item=catalog.Item(camp.Loot[0].Item);var count=camp.Loot[0].Count;Check(camp.Take(bag,0,revision),"take actual campsite slot");Check(!camp.Take(bag,0,revision) && bag.Model.CountItem(item)==count,"duplicate stale revision gives one reward");var snapshot=world.Chunks.CaptureFeatures().Single(f=>f.Id==camp.Id);camp.State.Opened=false;Check(snapshot.Site.Opened,"feature capture does not alias mutable state");camp.State.Opened=true;yield return Revisit(camp,"campsite");
            Step("well");Empty();var well=Approach(WorldAnchorKind.Well);Check(well.State.Water==3,"new shared well cap3");Select("waterskin");yield return Interact(well);Check(bag.SelectedStack.Charges==1 && bag.SelectedStack.Quality==LiquidState.Clean,"selected waterskin clean single serving, natural-water shortcut bypassed");revision=well.Revision;Check(well.Fill(bag,revision) && !well.Fill(bag,revision),"well stale duplicate rejected");Check(well.Fill(bag,well.Revision) && well.State.Water==0 && bag.SelectedStack.Charges==3,"well shared3 consumed, no full refill per charge");var waterBefore=JsonUtility.ToJson(well.State);Check(!well.Fill(bag,well.Revision),"empty well denied");yield return Shot("03-well-empty");yield return Revisit(well,"well");well=Approach(WorldAnchorKind.Well);var now=world.Renewal.Clock.Model.Elapsed;world.Renewal.Clock.Model.SetElapsed(now+479);Check(!well.Fill(bag,well.Revision),"no early well recharge");Empty();Select("empty_cup",2);world.Renewal.Clock.Model.SetElapsed(now+480);Check(well.Fill(bag,well.Revision) && bag.Model.CountItem(catalog.Item("clean_water_cup"))==1 && well.State.Water==0,"480 game seconds gives one clean cup");
            well.State.Water=1;well.State.RefillAt=now+960;Full();before=JsonUtility.ToJson(well.State);Check(!well.Fill(bag,well.Revision) && JsonUtility.ToJson(well.State)==before,"well full bag/no cup no lost charge");Empty();Select("waterskin");bag.Model.SetWater(bag.SelectedIndex,catalog.Item("waterskin"),1,LiquidState.Raw);Check(!well.Fill(bag,well.Revision) && well.State.Water==1,"raw partial container cannot transmute clean water");
            Step("quarry");var quarry=Anchor(WorldAnchorKind.Quarry);Move(quarry.Position+Vector2.down*2);var qs=world.Chunks.PoiState(quarry.Id);Check(qs.Nodes.Length==4,"four physical quarry nodes");var copper=qs.Nodes.Single(n=>world.Definition.Resources[n.Rule].Prefab.Definition.DropItem.Id=="copper_ore");var node=UnityEngine.Object.FindObjectsByType<ResourceIdentity>(FindObjectsSortMode.None).Single(n=>n.Id==copper.Id).Node;Check(node.Harvest(catalog.Item("pickaxe").Tool,10000,bag)==0 && node.Health.Current==node.Health.Maximum,"quarry retains Copper Iron-tool gate");var recovery=JsonUtility.ToJson(world.Renewal.CaptureRecovery());Full();Move(node.transform.position+Vector3.down);Check(node.Harvest(catalog.Item("iron_pickaxe").Tool,10000,bag)>0,"actual quarry harvest");yield return new WaitForSecondsRealtime(.9f);Check(WorldPickup.Active.Any(p=>p.Item==catalog.Item("copper_ore") && p.Count==6),"full bag keeps quarry ground pickup");Empty();Move(copper.Position);yield return new WaitForSecondsRealtime(.9f);Check(bag.Model.CountItem(catalog.Item("copper_ore"))==6,"actual pickup6 Copper");Check(!world.Renewal.Capture().Any(r=>r.Id.StartsWith("poi:")) && JsonUtility.ToJson(world.Renewal.CaptureRecovery())==recovery,"POI depletion adds no natural source delta/recovery debt");Check(qs.Nodes.Single(n=>n.Id==copper.Id).Destroyed,"quarry tombstone");yield return Shot("04-quarry-harvest");Move(world.Map.Spawn);yield return null;Move(quarry.Position);Check(world.Chunks.PoiState(quarry.Id).Nodes.Single(n=>n.Id==copper.Id).Destroyed && !UnityEngine.Object.FindObjectsByType<ResourceIdentity>(FindObjectsSortMode.None).Any(n=>n.Id==copper.Id),"quarry unload cannot replenish");
            Step("graveyard");Empty();var grave=Approach(WorldAnchorKind.Graveyard);FreezeGuards();Check(!grave.Secured,"graveyard locked before actual death");Check(grave.Use(bag.GetComponent<PlayerInteraction>()) && !CampLootPanel.IsOpen,"guarded feedback without objective modal");var spawner=world.GetComponent<ZombieSpawner>();var actorState=spawner.CaptureWorld().Single(e=>e.Feature==grave.GuardId);var guard=UnityEngine.Object.FindObjectsByType<EnemyController>(FindObjectsSortMode.None).Single(e=>(Vector2)e.transform.position==actorState.Position);Check(guard.PersistentGuard,"graveyard uses daytime encounter AI");var moved=(Vector2)guard.transform.position;guard.enabled=true;yield return new WaitForSecondsRealtime(.7f);guard.enabled=false;Check(Vector2.Distance(moved,guard.transform.position)>.05f || guard.State!=EnemyState.Idle,"daytime graveyard guard actually pursues player");guard.OwnHealth.ApplyDamage(5,true,bag);var hp=guard.OwnHealth.Current;var graveId=grave.Id;var guardId=grave.GuardId;var gravePosition=(Vector2)grave.transform.position;Move(world.Map.Spawn);yield return null;Check(spawner.CaptureWorld().Single(e=>e.Feature==guardId).HP==hp,"surface guard persists dormant in daytime");Move(gravePosition+Vector2.down*2);yield return new WaitForSecondsRealtime(.3f);FreezeGuards();grave=world.Chunks.ActivePoiSites[graveId];Check(!grave.Secured,"luring/unloading never unlocks cache");actorState=spawner.CaptureWorld().Single(e=>e.Feature==guardId);guard=UnityEngine.Object.FindObjectsByType<EnemyController>(FindObjectsSortMode.None).Single(e=>Vector2.Distance(e.transform.position,actorState.Position)<.1f);Check(guard.OwnHealth.Current==hp,"day guard restored exact HP");yield return Shot("05-graveyard-guarded");guard.OwnHealth.ApplyDamage(10000,true,bag);Check(grave.Secured && guard.OwnHealth.ApplyDamage(1)==0,"one guard death unlocks exactly once");yield return GraveSupplies();
            yield return AfterSites();
