        private static IEnumerator GraveSupplies()
        {var grave=Approach(WorldAnchorKind.Graveyard);Move((Vector2)grave.Location.position+Vector2.down*1.5f);yield return Interact(grave);var before=JsonUtility.ToJson(grave.State);Full();Check(!grave.Take(bag,0,grave.Revision) && before==JsonUtility.ToJson(grave.State),"guarded supplies full bag rollback");Empty();var revision=grave.Revision;Check(grave.Take(bag,0,revision) && !grave.Take(bag,0,revision),"graveyard shared bone slot claimed once");yield return Shot("06-graveyard-supplies");yield return Revisit(grave,"graveyard");
        }
        private static IEnumerator AfterSites()
        {
            Step("save-load");Check(save.Save(),"isolated Save11 "+save.LastError);var saved=save.Repository.Read(save.Validate);var states=saved.Features.Where(f=>f.Site!=null && f.Site.Schema==1).ToDictionary(f=>f.Id,f=>JsonUtility.ToJson(f.Site));save.Apply(saved);world.Chunks.DrainPending();yield return null;foreach(var pair in states)Check(JsonUtility.ToJson(world.Chunks.PoiState(pair.Key))==pair.Value,"saved POI exact remaining "+pair.Key);Check(save.Capture().Version==11 && world.Map.GenerationVersion==3,"Save11 generation3 unchanged");yield return Shot("07-save-load");
            Step("old-visited");var old=save.Capture();old.Features=old.Features.Select(f=>new WorldFeatureSnapshot{Id=f.Id,Visited=f.Visited,Cleared=f.Cleared}).ToArray();old.NightCreatures=old.NightCreatures.Where(e=>e.Feature==null || !e.Feature.EndsWith(":guard")).ToArray();old.Features=old.Features.Where(f=>!f.Id.EndsWith(":guard")).ToArray();save.Apply(old);world.Chunks.DrainPending();yield return null;foreach(var kind in new[]{WorldAnchorKind.Campsite,WorldAnchorKind.Well,WorldAnchorKind.Quarry,WorldAnchorKind.Graveyard}){var a=Anchor(kind);Move(a.Position);var s=world.Chunks.PoiState(a.Id);Check(s.Schema==1 && s.Legacy && s.Loot.All(slot=>slot.Count==0) && s.Nodes.Length==0 && s.Water==0,"old visited conservative additive policy "+kind);}Check(save.Save(),"legacy policy remains valid Save11 "+save.LastError);
            yield return Defense();
        }
        private static IEnumerator Defense()
        {
            Step("defense");Move(world.Map.Spawn);ContentExpansionQa.Clear(world.Map.Spawn,20);Empty();Select("bone_trap",2);var placement=bag.GetComponent<PlayerPlacement>();bag.GetComponent<CharacterFacing>().Face(Vector2.right);Check(placement.TryPlace(),"actual Bone Trap placement");var trap=WorldPlaceable.Active.Last(p=>p.Definition.Item.Id=="bone_trap");var position=(Vector2)trap.transform.position;var health=bag.GetComponent<Health>().Current;Move(position);yield return new WaitForFixedUpdate();Check(trap!=null && trap.Health.IsAlive && bag.GetComponent<Health>().Current==health,"trap friendly safety");Move(position+Vector2.left*3);var enemy=world.GetComponent<ZombieSpawner>().SpawnCavern(position,false);enemy.enabled=false;enemy.OwnHealth.RestoreHealth(32);yield return new WaitForFixedUpdate();yield return null;Check(!enemy.OwnHealth.IsAlive && (trap==null || !trap.Health.IsAlive),"Bone single target32 burst destroys trap");
            Select("spike_trap");Move(position+Vector2.down*3);bag.GetComponent<CharacterFacing>().Face(Vector2.up);Check(placement.TryPlace(),"actual Spike placement");var spike=WorldPlaceable.Active.Last(p=>p.Definition.Item.Id=="spike_trap");var e=world.GetComponent<ZombieSpawner>().SpawnCavern(spike.transform.position,false);e.enabled=false;e.OwnHealth.RestoreHealth(32);yield return new WaitForFixedUpdate();yield return null;Check(e.OwnHealth.Current==16 && spike.Health.IsAlive,"Spike first contact16 persistent");yield return new WaitForSeconds(1.3f);Check(!e.OwnHealth.IsAlive && spike.Health.IsAlive,"Spike repeated contact after1.2 seconds");yield return Shot("08-trap-roles");
