        }

        public static void BeginHost()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated QA required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.WorldRepository=new SaveRepository(Root+"/host/"+Guid.NewGuid().ToString("N")+"/world.json");host.ProfileOverride=Guid.NewGuid().ToString("N");host.NewWorldGenerationVersion=3;host.StartCoroutine(Guard(HostFlow()));}
        private static IEnumerator EnterHost()
        {var task=host.Host(ConnectionRoute.LocalNetwork);yield return new WaitUntil(()=>task.IsCompleted);Check(task.Result,"LAN Host "+host.LastFailure);Check(host.EnterGame(),"enter Host scene");var until=Time.realtimeSinceStartup+45;while(Time.realtimeSinceStartup<until){actor=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned && p.NetworkObject.IsPlayerObject);if(actor!=null && NetworkCreatureWorld.Active!=null && NetworkCreatureWorld.Active.Ready)break;yield return null;}Check(actor!=null && NetworkCreatureWorld.Active.Ready,"Host ready");bag=actor.GetComponent<PlayerInventory>();world=NetworkCreatureWorld.Active.World;catalog=NetworkCreatureWorld.Active.Catalog;actor.Motor.enabled=actor.GetComponent<PlayerInputAdapter>().enabled=false;var w=NetworkCreatureWorld.Active;w.Clock.enabled=w.Animals.enabled=w.Goblins.enabled=w.Night.enabled=world.Renewal.enabled=false;yield return null;}
        private static IEnumerator ReHost(){Check(host.TrySaveWorld(),"Host validates and writes Save11");host.Leave();yield return new WaitUntil(()=>host.State==NetworkSessionState.Idle);yield return new WaitForSecondsRealtime(.3f);yield return EnterHost();}
        private static IEnumerator HostFlow()
        {
            Step("host-shared-supplies");yield return EnterHost();Empty();var camp=Approach(WorldAnchorKind.Campsite);yield return null;Check(camp.GetComponent<NetworkPoiSite>().IsSpawned,"POI source registered as real NGO object");yield return Interact(camp);var request=actor.GetComponent<NetworkFacilityInteractor>();var inventory=actor.GetComponent<NetworkInventory>();var net=camp.GetComponent<NetworkPoiSite>();var rev=camp.Revision;var bRev=inventory.Revision.Value;var item=catalog.Item(camp.Loot[0].Item);var amount=camp.Loot[0].Count;
            Check(request.ExecutePoi(net.NetworkObjectId,0,rev,bRev),"Host transfer accepts current independent revisions");Check(!request.ExecutePoi(net.NetworkObjectId,0,rev,bRev),"Host duplicate loot rejected");Check(bag.Model.CountItem(item)==amount,"one finite shared reward");Check(!request.ExecutePoi(net.NetworkObjectId,1,camp.Revision,bRev),"stale bag revision independently rejected");yield return Shot("09-host-supplies");CampLootPanel.CloseFocused();
            var peers=new List<NetworkPlayer>();for(var i=0;i<3;i++){var p=UnityEngine.Object.Instantiate(host.PlayerPrefab,camp.Location.position+Vector3.down,Quaternion.identity).GetComponent<NetworkPlayer>();p.NetworkObject.Spawn();p.Motor.enabled=p.GetComponent<PlayerInputAdapter>().enabled=false;peers.Add(p);}yield return null;
            var slot=Array.FindIndex(camp.Loot,s=>s.Count>0);rev=camp.Revision;var winners=0;foreach(var p in new[]{actor}.Concat(peers)){var inv=p.GetComponent<NetworkInventory>();if(p.GetComponent<NetworkFacilityInteractor>().ExecutePoi(net.NetworkObjectId,slot,rev,inv.Revision.Value))winners++;}Check(winners==1,"four simulated server participants racing one revision produce one winner, no x4 loot");foreach(var p in peers)p.NetworkObject.Despawn();
            var campId=camp.Id;var campState=JsonUtility.ToJson(camp.State);var campPosition=(Vector2)camp.transform.position;
            Step("host-well-mining-guard");Empty();var well=Approach(WorldAnchorKind.Well);Select("waterskin");yield return Interact(well);Check(bag.SelectedStack.Charges==1 && well.State.Water==2,"Host actual interact fills one clean charge");var wellId=well.Id;var wellState=JsonUtility.ToJson(well.State);
            var quarry=Anchor(WorldAnchorKind.Quarry);Move(quarry.Position);var qs=world.Chunks.PoiState(quarry.Id);Check(qs.Nodes.Length>0,"Host actual quarry resources");var nodeState=qs.Nodes[0];var node=UnityEngine.Object.FindObjectsByType<ResourceIdentity>(FindObjectsSortMode.None).Single(n=>n.Id==nodeState.Id).Node;Check(node.GetComponent<NetworkResource>().IsSpawned && node.Harvest(catalog.Item("diamond_pickaxe").Tool,10000,bag)>0,"Host network quarry harvest");yield return null;var quarryState=JsonUtility.ToJson(qs);
            var grave=Approach(WorldAnchorKind.Graveyard);FreezeGuards();var graveId=grave.Id;var gravePosition=(Vector2)grave.transform.position;Check(!grave.Secured,"Host guarded cache locked");var guardState=world.GetComponent<ZombieSpawner>().CaptureWorld().Single(s=>s.Feature==grave.GuardId);var enemy=UnityEngine.Object.FindObjectsByType<EnemyController>(FindObjectsSortMode.None).Single(e=>Vector2.Distance(e.transform.position,guardState.Position)<.1f);enemy.OwnHealth.ApplyDamage(5,true,bag);var hp=enemy.OwnHealth.Current;var guardId=grave.GuardId;yield return Shot("10-host-guarded");
            Step("host-rehost");yield return ReHost();world.Chunks.DrainPending();yield return null;Check(world.GetComponent<ZombieSpawner>().CaptureWorld().Single(s=>s.Feature==guardId).HP==hp,"daytime surface guard exact HP survives actual reHost");Check(!world.Chunks.FeatureCleared(guardId),"reHost cannot unlock living guard");Check(JsonUtility.ToJson(world.Chunks.PoiState(campId))==campState,"reHost retains claimed campsite slot");Check(JsonUtility.ToJson(world.Chunks.PoiState(wellId))==wellState,"reHost retains spent water and due time");Check(JsonUtility.ToJson(world.Chunks.PoiState(quarry.Id))==quarryState,"reHost retains quarry tombstone");
            Move(gravePosition);yield return new WaitForSecondsRealtime(.3f);FreezeGuards();grave=world.Chunks.ActivePoiSites[graveId];guardState=world.GetComponent<ZombieSpawner>().CaptureWorld().Single(s=>s.Feature==guardId);enemy=UnityEngine.Object.FindObjectsByType<EnemyController>(FindObjectsSortMode.None).Single(e=>Vector2.Distance(e.transform.position,guardState.Position)<.1f);enemy.OwnHealth.ApplyDamage(10000,true,bag);Check(grave.Secured && grave.GetComponent<NetworkPoiSite>().State.Value.Secured,"guard death publishes shared security");Move((Vector2)grave.Location.position+Vector2.down);request=actor.GetComponent<NetworkFacilityInteractor>();inventory=actor.GetComponent<NetworkInventory>();rev=grave.Revision;Check(request.ExecutePoi(grave.GetComponent<NetworkPoiSite>().NetworkObjectId,0,rev,inventory.Revision.Value),"Host claims graveyard Bone");var graveState=JsonUtility.ToJson(grave.State);yield return ReHost();world.Chunks.DrainPending();yield return null;Check(world.Chunks.FeatureCleared(guardId) && JsonUtility.ToJson(world.Chunks.PoiState(graveId))==graveState && !world.GetComponent<ZombieSpawner>().CaptureWorld().Any(s=>s.Feature==guardId),"cleared graveyard/remaining loot persists, no guard respawn on reHost");yield return Shot("11-host-rehost");
        }

        private static IEnumerator DefenseNavigation()
        {
            Step("defense-navigation");Move(world.Map.Spawn);ContentExpansionQa.Clear(world.Map.Spawn,22);var origin=world.Map.Spawn;
            foreach(var p in WorldPlaceable.Active.ToArray())if(Vector2.Distance(p.transform.position,origin)<20)PrefabPool.Release(p.gameObject);
            yield return null;var gate=UnityEngine.Object.Instantiate(catalog.Item("wood_gate").Placement.Prefab,origin,Quaternion.identity);var door=gate.GetComponent<WorldDoor>();foreach(var side in new[]{-1,1})UnityEngine.Object.Instantiate(catalog.Item("wood_wall").Placement.Prefab,origin+Vector2.right*(side*2.8f),Quaternion.identity);
            Move(origin+Vector2.down*3);var enemy=world.GetComponent<ZombieSpawner>().SpawnCavern(origin+Vector2.up*2,false);enemy.PersistentGuard=true;enemy.enabled=true;Physics2D.SyncTransforms();yield return new WaitForSeconds(3.5f);Check(gate.Health.Current<gate.Health.Maximum && enemy.transform.position.y>=origin.y-.4f,"actual enemy pursues player, closed gate blocks and takes structure damage");enemy.enabled=false;Check(door.Toggle(),"actual gate open action");yield return new WaitForSeconds(.4f);Check(!door.Barrier.enabled,"gate opens collider after animation");var nav=world.GetComponent<WorldNavigation>();Check(nav.CanMove(origin+Vector2.down,Vector2.up,2,.25f),"gate choke becomes traversable");enemy.enabled=true;yield return new WaitForSeconds(1.5f);Check(enemy.transform.position.y<origin.y+.3f,"enemy traverses opened choke instead of staying on structure");yield return Shot("12-defense-choke");enemy.enabled=false;enemy.OwnHealth.ApplyDamage(10000,true,bag);
            Vector2 center=default;var found=false;for(var x=7;x<19 && !found;x+=3)for(var y=4;y<19;y+=3){var p=origin+new Vector2(x,y);if(nav.CanSpawn(p,.6f,0,false)){center=p;found=true;break;}}Check(found,"baseline open spawn candidate");foreach(var dir in new[]{Vector2.up,Vector2.down,Vector2.left,Vector2.right})UnityEngine.Object.Instantiate(catalog.Item("wood_wall").Placement.Prefab,center+dir*2,Quaternion.Euler(0,0,dir.x==0?0:90));Physics2D.SyncTransforms();Check(!nav.CanSpawn(center,.6f,0,false),"shared navigation rejects creature spawn enclosed by player barriers");
        }

        public static void BeginCoopHost()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated QA required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.WorldRepository=new SaveRepository(Root+"/coop/"+Guid.NewGuid().ToString("N")+"/world.json");host.ProfileOverride=Guid.NewGuid().ToString("N");host.NewWorldGenerationVersion=3;host.StartCoroutine(Guard(CoopHost()));}
        public static void BeginCoopClient()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated QA required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.ProfileOverride=Guid.NewGuid().ToString("N");host.StartCoroutine(Guard(CoopClient()));}
        private static void PeerMove(NetworkPlayer peer,Vector2 p)
        {peer.transform.position=p;peer.GetComponent<Rigidbody2D>().position=p;peer.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;peer.GetComponent<CharacterFacing>().Face(Vector2.up);peer.GetComponent<PlayerInputCommands>().SetMove(Vector2.zero);Physics2D.SyncTransforms();world.Chunks.Reconcile();world.Chunks.DrainPending();NetworkCreatureWorld.Active.FlushPending();}
        private static IEnumerator CoopHost()
        {
            Application.runInBackground=true;yield return EnterHost();Step("coop-host-ready");var until=Time.realtimeSinceStartup+180;NetworkPlayer peer=null;
            while(Time.realtimeSinceStartup<until){peer=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned && p.NetworkObject.IsPlayerObject && !p.IsOwner);if(peer!=null)break;yield return null;}Check(peer!=null,"actual separate-process Client joined");peer.Motor.enabled=false;var remote=peer.GetComponent<PlayerInventory>();
