        private static PoiSite clientSite;
        private static IEnumerator ClientSite(WorldAnchorKind kind)
        {var until=Time.realtimeSinceStartup+80;clientSite=null;while(Time.realtimeSinceStartup<until){clientSite=UnityEngine.Object.FindObjectsByType<PoiSite>(FindObjectsSortMode.None).FirstOrDefault(s=>s.State!=null && s.Kind==kind && s.InRange(bag));if(clientSite!=null)break;yield return null;}Check(clientSite!=null,"Client replicated nearby "+kind);bag.GetComponent<CharacterFacing>().Face((Vector2)clientSite.Location.position-(Vector2)bag.transform.position);yield return new WaitForSecondsRealtime(.3f);}
        private static IEnumerator CoopClient()
        {
            Application.runInBackground=true;Step("coop-client-join");var task=host.Join(ConnectionRoute.LocalNetwork,"127.0.0.1");yield return new WaitUntil(()=>task.IsCompleted);Check(task.Result,"Client LAN transport started");var until=Time.realtimeSinceStartup+60;while(Time.realtimeSinceStartup<until){actor=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned && p.IsOwner && p.NetworkObject.IsPlayerObject);if(actor!=null && NetworkCreatureWorld.Active!=null)break;yield return null;}Check(actor!=null,"real Client owner spawned");bag=actor.GetComponent<PlayerInventory>();world=NetworkCreatureWorld.Active.World;catalog=NetworkCreatureWorld.Active.Catalog;actor.GetComponent<PlayerInputAdapter>().enabled=false;
            yield return ClientSite(WorldAnchorKind.Campsite);Check(clientSite.Catalog==catalog && clientSite.Loot.Count(s=>s.Count>0)==3,"Client displays Host rolled supplies without local initialization");var item=catalog.Item(clientSite.Loot[0].Item);var amount=clientSite.Loot[0].Count;yield return Interact(clientSite);until=Time.realtimeSinceStartup+5;while(Time.realtimeSinceStartup<until && clientSite.Revision==0)yield return null;var panel=UnityEngine.Object.FindFirstObjectByType<CampLootPanel>();Check(panel!=null && panel.Take(0),"real Client existing supplies UI sends owner request");until=Time.realtimeSinceStartup+8;while(Time.realtimeSinceStartup<until && bag.Model.CountItem(item)<amount)yield return null;Check(bag.Model.CountItem(item)==amount && clientSite.Loot[0].Count==0,"Client confirms inventory and shared slot replica");CampLootPanel.CloseFocused();
            yield return ClientSite(WorldAnchorKind.Well);until=Time.realtimeSinceStartup+8;while(Time.realtimeSinceStartup<until && bag.Model.CountItem(catalog.Item("waterskin"))==0)yield return null;var slot=Enumerable.Range(0,36).First(i=>bag.Model.GetSlot(i).Item==catalog.Item("waterskin"));bag.SelectSlot(slot);yield return new WaitForSecondsRealtime(.7f);var revision=clientSite.Revision;yield return Interact(clientSite);Check(actor.GetComponent<NetworkFacilityInteractor>().PoiInteract(clientSite,-2,revision),"Client queues duplicate stale well request");until=Time.realtimeSinceStartup+8;while(Time.realtimeSinceStartup<until && bag.SelectedStack.Charges==0)yield return null;yield return new WaitForSecondsRealtime(.5f);Check(bag.SelectedStack.Charges==1 && clientSite.State.Water==2,"Client clean charge and finite shared water replica");
            yield return ClientSite(WorldAnchorKind.Graveyard);Check(!clientSite.Secured,"Client sees guarded state");var ni=Enumerable.Range(0,36).FirstOrDefault(i=>bag.Model.GetSlot(i).IsEmpty);bag.SelectSlot(ni);yield return new WaitForSecondsRealtime(.5f);yield return Interact(clientSite);Check(!CampLootPanel.IsOpen,"Client guarded feedback prevents opening");until=Time.realtimeSinceStartup+15;while(Time.realtimeSinceStartup<until && !clientSite.Secured)yield return null;Check(clientSite.Secured,"Host death updates Client security without local death roll");yield return Interact(clientSite);until=Time.realtimeSinceStartup+4;var rev=clientSite.Revision;while(Time.realtimeSinceStartup<until && rev==clientSite.Revision)yield return null;panel=UnityEngine.Object.FindFirstObjectByType<CampLootPanel>();Check(panel!=null && panel.Take(0),"Client claims cleared graveyard from same supplies UI");until=Time.realtimeSinceStartup+8;while(Time.realtimeSinceStartup<until && bag.Model.CountItem(catalog.Item("bone"))<3)yield return null;Check(bag.Model.CountItem(catalog.Item("bone"))==3,"Client confirms exactly Bone3");CampLootPanel.CloseFocused();host.Leave();yield return new WaitUntil(()=>host.State==NetworkSessionState.Idle);
        }

        public static void BeginGuardBoundary()
        {ContentExpansionQa.Prepare();save=ContentExpansionQa.S;bag=save.Player;world=save.World;catalog=save.Catalog;world.Animals.enabled=world.Renewal.enabled=false;save.StartCoroutine(Guard(GuardBoundary()));}
        private static IEnumerator GuardBoundary()
        {
            Step("guard-boundary");var site=Approach(WorldAnchorKind.Graveyard);yield return new WaitForSecondsRealtime(.3f);FreezeGuards();var s=world.GetComponent<ZombieSpawner>().CaptureWorld().Single(e=>e.Feature==site.GuardId);var enemy=UnityEngine.Object.FindObjectsByType<EnemyController>(FindObjectsSortMode.None).Single(e=>Vector2.Distance(e.transform.position,s.Position)<.1f);Check(enemy.PersistentGuard && enemy.GuardHome==(Vector2)site.transform.position,"guard home derives from stable anchor");var hp=enemy.OwnHealth.Current;var home=enemy.GuardHome;Move(home+Vector2.down*20);enemy.enabled=true;yield return new WaitForSecondsRealtime(5);Check(Vector2.Distance(enemy.transform.position,home)<enemy.GuardLeash && !site.Secured && enemy.OwnHealth.Current==hp,"lured guard returns locally, keeps HP and cannot unlock supplies");Move(home+Vector2.down*3);yield return new WaitForSecondsRealtime(.8f);Check(enemy.State!=EnemyState.Idle,"daytime guard resumes local pursuit");yield return Shot("16-guard-boundary");
        }
